import os
from typing import List

def list_files(directory: str) -> List[str]:
    """Lists files and directories within a given directory."""
    try:
        return [f for f in os.listdir(directory) if os.path.join(directory, f) != "."]
    except OSError as e:
        print(f"Error listing directory {directory}: {e}")
        return []

def write_file(filename: str, content: str):
    """Writes content to a file."""
    try:
        with open(filename, "w") as f:
            f.write(content)
    except OSError as e:
        print(f"Error writing to file {filename}: {e}")

def read_file(filename: str) -> str:
    """Reads the content of a file."""
    try:
        with open(filename, "r") as f:
            return f.read()
    except OSError as e:
        print(f"Error reading file {filename}: {e}")
        return ""

def main():
    # Create a dummy toolkit directory if it doesn't exist
    toolkit_dir = "toolkit"
    if not os.path.exists(toolkit_dir):
        os.makedirs(toolkit_dir)

    # Example usage: creating and reading files
    file1 = os.path.join(toolkit_dir, "file1.txt")
    write_file(file1, "This is the content of file1.")
    content1 = read_file(file1)
    print(f"Content of {file1}: {content1}")

    files = list_files(toolkit_dir)
    print(f"Files in toolkit directory: {files}")
